/* @flow */
import Auth0 from 'auth0-js';
import Cookie from 'js-cookie';
import keys from '../config/keys';

const ACCESS_TOKEN_COOKIE_NAME = 'numvalidateAccessToken';

let auth0WebAuth;

const initialize = () => {
  auth0WebAuth = new Auth0.WebAuth({
    domain: keys.AUTH0_DOMAIN,
    clientID: keys.AUTH0_CLIENT_ID,
    redirectUri: `${window.location.origin}/dashboard`,
    audience: keys.AUTH0_AUDIENCE,
    responseType: 'token id_token',
    scope: 'openid',
  });
};

const setAuthCookie = (accessToken: string, tokenExpiresIn: number) => {
  if (!process.browser) {
    return;
  }
  const cookieExpiry = new Date(new Date().getTime() + tokenExpiresIn * 1000);
  Cookie.set(ACCESS_TOKEN_COOKIE_NAME, accessToken, { expires: cookieExpiry });
};

const removeAuthCookie = () => {
  if (!process.browser) {
    return;
  }
  Cookie.remove(ACCESS_TOKEN_COOKIE_NAME);
};

const authorize = () => {
  auth0WebAuth.authorize();
};

const logout = () => {
  if (!process.browser) {
    return;
  }
  removeAuthCookie();
  window.localStorage.setItem('loggedOutAt', Date.now());
};

const getAccessToken = (req?: any): ?string => {
  if (process.browser) {
    return Cookie.getJSON(ACCESS_TOKEN_COOKIE_NAME);
  } else {
    if (!req || !req.headers || !req.headers.cookie) {
      return undefined;
    }
    const accessTokenCookie = req.headers.cookie
      .split(';')
      .find(cookie => cookie.trim().startsWith(`${ACCESS_TOKEN_COOKIE_NAME}=`));
    if (!accessTokenCookie) {
      return undefined;
    }
    return accessTokenCookie.split('=')[1];
  }
};

const isAuthenticated = (req?: any): boolean => {
  return getAccessToken(req) !== undefined;
};

const parseHash = async (): Promise<?string> => {
  return new Promise((resolve, reject) => {
    auth0WebAuth.parseHash(window.location.hash, (err, authResult) => {
      if (authResult && authResult.accessToken && authResult.expiresIn) {
        setAuthCookie(authResult.accessToken, authResult.expiresIn);
        return resolve(authResult.accessToken);
      } else if (err) {
        return reject(err);
      } else {
        if (isAuthenticated()) {
          return resolve();
        } else {
          return reject(`authResult: ${authResult}`);
        }
      }
    });
  });
};

export default {
  authorize,
  parseHash,
  logout,
  getAccessToken,
  isAuthenticated,
  initialize,
};

const PNF = require('google-libphonenumber').PhoneNumberFormat;
const phoneUtil = require('google-libphonenumber').PhoneNumberUtil.getInstance();
const countries = require('../static/countries.json');

/**
 * GET /api/countries
 * 
 * @return {Object} The countries supported by this API.
 */
exports.getCountries = async ctx => {
  ctx.body = { data: countries };
};

/**
 * GET /api/validate
 * 
 * @param {String} number The phone number to validate.
 * @param {String} countryCode The country code of phone number to validate.
 * @return {Object} The validation result.
 */
exports.validate = async (ctx, next) => {
  ctx
    .validateQuery('number')
    .required()
    .isString();
  ctx
    .validateQuery('countryCode')
    .optional()
    .isString();
  const { number, countryCode } = ctx.vals;
  let numberToCheck = !countryCode ? `+${number}` : number;
  let result = {
    valid: false,
    number: undefined,
    e164Format: undefined,
    internationalFormat: undefined,
    nationalFormat: undefined,
    countryCode: undefined,
    countryPrefix: undefined,
    countryName: undefined,
  };
  result.number = number;
  result.countryCode = countryCode;
  try {
    const parsedNumber = phoneUtil.parseAndKeepRawInput(numberToCheck, countryCode);
    result.valid = phoneUtil.isValidNumber(parsedNumber);
    if (result.valid) {
      result.number = number;
      result.e164Format = phoneUtil.format(parsedNumber, PNF.E164);
      result.internationalFormat = phoneUtil.format(parsedNumber, PNF.INTERNATIONAL);
      result.nationalFormat = phoneUtil.format(parsedNumber, PNF.NATIONAL);
      result.countryCode = phoneUtil.getRegionCodeForNumber(parsedNumber);
      result.countryPrefix = countries[result.countryCode].countryPrefix;
      result.countryName = countries[result.countryCode].countryName;
    }
  } catch (err) {
    console.log('Parsing error: ', err);
  }

  ctx.body = { data: result };
};

const _ = require('lodash');
const commonUtils = require('../utils/common');
const redisService = require('../services/redis');
const auth0Service = require('../services/auth0');

module.exports = async (ctx, next) => {
  const apiTokenHeader = commonUtils.getObjectKey(ctx.headers, 'x-api-token');
  console.info('Has API token? ', apiTokenHeader !== undefined);
  if (!apiTokenHeader) {
    console.info('Missing API token');
    return next();
  }
  const apiToken = ctx.headers[apiTokenHeader];
  console.info('API token? ', apiToken);
  if (!commonUtils.isApiTokenValid(apiToken)) {
    console.info('Invalid API token');
    ctx.throw(400, 'Invalid API token');
  }
  let userId = await redisService.getUserIdByApiToken(apiToken);
  const isApiTokenCached = !_.isNil(userId);
  console.info('Is API token cached? ', isApiTokenCached);
  if (!isApiTokenCached) {
    const user = await auth0Service.getUserByApiToken(ctx.app.auth0Token, apiToken);
    console.info('Is API token assigned to an user? ', user !== undefined);
    if (!user) {
      ctx.throw(400, 'Invalid API token');
    }
    userId = user.user_id;
    await redisService.setApiToken(apiToken, userId);
  }
  console.info('User id: ', userId);
  ctx.state.apiToken = apiToken;
  ctx.state.userId = userId;
  return next();
};

const Redis = require('ioredis');
const keys = require('../config/keys');

const redis = new Redis(keys.REDIS_URL);

exports.getRedis = () => {
  return redis;
};

exports.getMaxRequestsByUserId = async userId => {
  const key = `user_id_to_max_requests:${userId}`;
  const result = await redis.get(key);
  return result;
};

exports.setUserMaxRequests = async (userId, maxRequests) => {
  const key = `user_id_to_max_requests:${userId}`;
  const result = await redis.set(key, maxRequests, 'EX', keys.REDIS_CACHE_EXPIRY_IN_MS);
  return result;
};

exports.getUserIdByApiToken = async apiToken => {
  const key = `token_to_user_id:${apiToken}`;
  const result = await redis.get(key);
  return result;
};

exports.setApiToken = async (apiToken, userId) => {
  const key = `token_to_user_id:${apiToken}`;
  const result = await redis.set(key, userId, 'EX', keys.REDIS_CACHE_EXPIRY_IN_MS);
  return result;
};

exports.removeUserCache = async (userId, apiTokens) => {
  // TODO: CHECK
  const limitKey = `limit:${userId}`;
  await redis.del(limitKey);
  const maxKey = `user_id_to_max_requests:${userId}`;
  await redis.del(maxKey);
  if (apiTokens && Array.isArray(apiTokens)) {
    for (const apiToken of apiTokens) {
      const tokenKey = `token_to_user_id:${apiToken}`;
      await redis.del(tokenKey);
    }
  }
};

import {
